loop14:
  ;; ==== loop chunk: AES + fold of the chunk before last + products of the previous chunk
  ;; -- slot 0
  vpternlogq zmm.mid, zmm.lo, zmm.hi, 0x96      ; Karatsuba: mid = sum of the cross terms
  vpslldq zmm.r1, zmm.mid, 8
  vpsrldq zmm.r2, zmm.mid, 8
  vpxorq zmm.fl, zmm.lo, zmm.r1                ; mid folds into lo/hi (gcm_mul_raw)
  vpxorq zmm.fh, zmm.hi, zmm.r2
  vextracti64x4 ymm.r1, zmm.fl, 1
  vpxorq ymm.fl, ymm.fl, ymm.r1
  vextracti32x4 xmm.r1, ymm.fl, 1
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vpclmulqdq zmm.lo, zmm.e1, zmmword ptr [q.htab + 64], 0x00
  vpclmulqdq zmm.hi, zmm.e1, zmmword ptr [q.htab + 64], 0x11
  vpshufd zmm.t2, zmm.e1, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e1                  ; a0 ^ a1 in both halves
  vpaddd zmm.s0, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 0]
  vpaddd zmm.s1, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 64]
  vpaddd zmm.s2, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 128]
  vpaddd zmm.s3, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 192]
  vpaddd zmm.s4, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 256]
  vpaddd zmm.s5, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 320]
  vpaddd zmm.s6, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 384]
  vpaddd zmm.s7, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 448]
  ;; -- slot 1
  vextracti64x4 ymm.r2, zmm.fh, 1
  vpxorq ymm.fh, ymm.fh, ymm.r2
  vextracti32x4 xmm.r2, ymm.fh, 1
  vpxorq xmm.fh, xmm.fh, xmm.r2                ; four lanes to one
  vpclmulqdq zmm.mid, zmm.t2, zmmword ptr [q.htab + 576], 0x00
  vpclmulqdq zmm.t, zmm.e2, zmmword ptr [q.htab + 128], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e2, zmmword ptr [q.htab + 128], 0x11
  vbroadcasti32x4 zmm.k, xmmword ptr [q.rk]
  vpshufb zmm.s0, zmm.s0, zmm.bswap
  vpshufb zmm.s1, zmm.s1, zmm.bswap
  vpshufb zmm.s2, zmm.s2, zmm.bswap
  vpshufb zmm.s3, zmm.s3, zmm.bswap
  vpshufb zmm.s4, zmm.s4, zmm.bswap
  vpshufb zmm.s5, zmm.s5, zmm.bswap
  vpshufb zmm.s6, zmm.s6, zmm.bswap
  vpshufb zmm.s7, zmm.s7, zmm.bswap
  vpxorq zmm.s0, zmm.s0, zmm.k
  vpxorq zmm.s1, zmm.s1, zmm.k
  vpxorq zmm.s2, zmm.s2, zmm.k
  vpxorq zmm.s3, zmm.s3, zmm.k
  vpxorq zmm.s4, zmm.s4, zmm.k
  vpxorq zmm.s5, zmm.s5, zmm.k
  vpxorq zmm.s6, zmm.s6, zmm.k
  vpxorq zmm.s7, zmm.s7, zmm.k
  ;; -- slot 2
  vpslld xmm.r1, xmm.fl, 31                    ; fold modulo the polynomial (table rows carry x^-1)
  vpslld xmm.r2, xmm.fl, 30
  vpslld xmm.r3, xmm.fl, 25
  vpxorq xmm.r1, xmm.r1, xmm.r2
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e2, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e2
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 640], 0x00
  vbroadcasti32x4 zmm.k, xmmword ptr [q.rk + 16]
  vaesenc zmm.s0, zmm.s0, zmm.k
  vaesenc zmm.s1, zmm.s1, zmm.k
  vaesenc zmm.s2, zmm.s2, zmm.k
  vaesenc zmm.s3, zmm.s3, zmm.k
  vaesenc zmm.s4, zmm.s4, zmm.k
  vaesenc zmm.s5, zmm.s5, zmm.k
  vaesenc zmm.s6, zmm.s6, zmm.k
  vaesenc zmm.s7, zmm.s7, zmm.k
  ;; -- slot 3
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpsrldq xmm.r2, xmm.r1, 4
  vpslldq xmm.r1, xmm.r1, 12
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpclmulqdq zmm.t, zmm.e3, zmmword ptr [q.htab + 192], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e3, zmmword ptr [q.htab + 192], 0x11
  vbroadcasti32x4 zmm.k, xmmword ptr [q.rk + 32]
  vaesenc zmm.s0, zmm.s0, zmm.k
  vaesenc zmm.s1, zmm.s1, zmm.k
  vaesenc zmm.s2, zmm.s2, zmm.k
  vaesenc zmm.s3, zmm.s3, zmm.k
  vaesenc zmm.s4, zmm.s4, zmm.k
  vaesenc zmm.s5, zmm.s5, zmm.k
  vaesenc zmm.s6, zmm.s6, zmm.k
  vaesenc zmm.s7, zmm.s7, zmm.k
  ;; -- slot 4
  vpsrld xmm.r1, xmm.fl, 1
  vpsrld xmm.r3, xmm.fl, 2
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpsrld xmm.r3, xmm.fl, 7
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e3, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e3
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 704], 0x00
  vbroadcasti32x4 zmm.k, xmmword ptr [q.rk + 48]
  vaesenc zmm.s0, zmm.s0, zmm.k
  vaesenc zmm.s1, zmm.s1, zmm.k
  vaesenc zmm.s2, zmm.s2, zmm.k
  vaesenc zmm.s3, zmm.s3, zmm.k
  vaesenc zmm.s4, zmm.s4, zmm.k
  vaesenc zmm.s5, zmm.s5, zmm.k
  vaesenc zmm.s6, zmm.s6, zmm.k
  vaesenc zmm.s7, zmm.s7, zmm.k
  ;; -- slot 5
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpxorq xmm.r1, xmm.r1, xmm.r2
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vpxorq xmm.acc, xmm.fh, xmm.fl
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpclmulqdq zmm.t, zmm.e4, zmmword ptr [q.htab + 256], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e4, zmmword ptr [q.htab + 256], 0x11
  vbroadcasti32x4 zmm.k, xmmword ptr [q.rk + 64]
  vaesenc zmm.s0, zmm.s0, zmm.k
