  vpternlogq zmm.mid, zmm.lo, zmm.hi, 0x96      ; Karatsuba: mid = sum of the cross terms
  vpslldq zmm.r1, zmm.mid, 8
  vpsrldq zmm.r2, zmm.mid, 8
  vpxorq zmm.fl, zmm.lo, zmm.r1                ; mid folds into lo/hi (gcm_mul_raw)
  vpxorq zmm.fh, zmm.hi, zmm.r2
  vextracti64x4 ymm.r1, zmm.fl, 1
  vpxorq ymm.fl, ymm.fl, ymm.r1
  vextracti32x4 xmm.r1, ymm.fl, 1
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vpclmulqdq zmm.lo, zmm.e1, zmmword ptr [q.htab + 64], 0x00
  vpclmulqdq zmm.hi, zmm.e1, zmmword ptr [q.htab + 64], 0x11
  vpshufd zmm.t2, zmm.e1, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e1                  ; a0 ^ a1 in both halves
