  vpaddd zmm.s1, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 64]
  vpaddd zmm.s2, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 128]
  vpaddd zmm.s3, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 192]
  vpaddd zmm.s4, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 256]
  vpaddd zmm.s5, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 320]
  vpaddd zmm.s6, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 384]
  vpaddd zmm.s7, zmm.base, zmmword ptr [rip + gcm_vaes_inc + 448]
  ;; -- slot 1
  vextracti64x4 ymm.r2, zmm.fh, 1
  vpxorq ymm.fh, ymm.fh, ymm.r2
  vextracti32x4 xmm.r2, ymm.fh, 1
  vpxorq xmm.fh, xmm.fh, xmm.r2                ; four lanes to one
  vpclmulqdq zmm.mid, zmm.t2, zmmword ptr [q.htab + 576], 0x00
  vpclmulqdq zmm.t, zmm.e2, zmmword ptr [q.htab + 128], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e2, zmmword ptr [q.htab + 128], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vbroadcasti32x4 zmm.k, xmmword ptr [q.rk]
  vpshufb zmm.s0, zmm.s0, zmm.bswap
  vpshufb zmm.s1, zmm.s1, zmm.bswap
  vpshufb zmm.s2, zmm.s2, zmm.bswap
  vpshufb zmm.s3, zmm.s3, zmm.bswap
  vpshufb zmm.s4, zmm.s4, zmm.bswap
  vpshufb zmm.s5, zmm.s5, zmm.bswap
  vpshufb zmm.s6, zmm.s6, zmm.bswap
  vpshufb zmm.s7, zmm.s7, zmm.bswap
  vpxorq zmm.s0, zmm.s0, zmm.k
  vpxorq zmm.s1, zmm.s1, zmm.k
  vpxorq zmm.s2, zmm.s2, zmm.k
  vpxorq zmm.s3, zmm.s3, zmm.k
  vpxorq zmm.s4, zmm.s4, zmm.k
  vpxorq zmm.s5, zmm.s5, zmm.k
  vpxorq zmm.s6, zmm.s6, zmm.k
  vpxorq zmm.s7, zmm.s7, zmm.k
