  vpslld xmm.r2, xmm.fl, 30
  vpslld xmm.r3, xmm.fl, 25
  vpxorq xmm.r1, xmm.r1, xmm.r2
  vpshufd zmm.t2, zmm.e2, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e2
