  vpsrld xmm.r3, xmm.fl, 2
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpsrld xmm.r3, xmm.fl, 7
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 704], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpclmulqdq zmm.t, zmm.e4, zmmword ptr [q.htab + 256], 0x00
