  vpclmulqdq zmm.t, zmm.e5, zmmword ptr [q.htab + 320], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e5, zmmword ptr [q.htab + 320], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vbroadcasti32x4 zmm.k, xmmword ptr [q.rk + 80]
  vaesenc zmm.s0, zmm.s0, zmm.k
  vaesenc zmm.s1, zmm.s1, zmm.k
  vaesenc zmm.s2, zmm.s2, zmm.k
  vaesenc zmm.s3, zmm.s3, zmm.k
  vaesenc zmm.s4, zmm.s4, zmm.k
  vaesenc zmm.s5, zmm.s5, zmm.k
  vaesenc zmm.s6, zmm.s6, zmm.k
