  vaesenc zmm.s1, zmm.s1, zmm.k
  vaesenc zmm.s2, zmm.s2, zmm.k
  vaesenc zmm.s3, zmm.s3, zmm.k
  vaesenc zmm.s4, zmm.s4, zmm.k
  vaesenc zmm.s5, zmm.s5, zmm.k
  vaesenc zmm.s6, zmm.s6, zmm.k
  vaesenc zmm.s7, zmm.s7, zmm.k
  ;; -- slot 10
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e7, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e7
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 960], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vbroadcasti32x4 zmm.k, xmmword ptr [q.rk + 144]
