decrypt12_l:
  vmovdqu64 zmm.e0, zmmword ptr [q.in + 0]     ; decrypt: the ciphertext is the input (loaded before the store: in-place safe)
  vmovdqu64 zmm.e1, zmmword ptr [q.in + 64]     ; decrypt: the ciphertext is the input (loaded before the store: in-place safe)
  vmovdqu64 zmm.e2, zmmword ptr [q.in + 128]     ; decrypt: the ciphertext is the input (loaded before the store: in-place safe)
  vmovdqu64 zmm.e3, zmmword ptr [q.in + 192]     ; decrypt: the ciphertext is the input (loaded before the store: in-place safe)
  vmovdqu64 zmm.e4, zmmword ptr [q.in + 256]     ; decrypt: the ciphertext is the input (loaded before the store: in-place safe)
  vmovdqu64 zmm.e5, zmmword ptr [q.in + 320]     ; decrypt: the ciphertext is the input (loaded before the store: in-place safe)
  vmovdqu64 zmm.e6, zmmword ptr [q.in + 384]     ; decrypt: the ciphertext is the input (loaded before the store: in-place safe)
  vmovdqu64 zmm.e7, zmmword ptr [q.in + 448]     ; decrypt: the ciphertext is the input (loaded before the store: in-place safe)
