  vmovdqu64 zmmword ptr [q.out + 0], zmm.s0
  vpxorq zmm.s1, zmm.s1, zmm.e1
  vmovdqu64 zmmword ptr [q.out + 64], zmm.s1
  vpxorq zmm.s2, zmm.s2, zmm.e2
  vmovdqu64 zmmword ptr [q.out + 128], zmm.s2
  vpxorq zmm.s3, zmm.s3, zmm.e3
  vmovdqu64 zmmword ptr [q.out + 192], zmm.s3
  vpxorq zmm.s4, zmm.s4, zmm.e4
  vmovdqu64 zmmword ptr [q.out + 256], zmm.s4
  vpxorq zmm.s5, zmm.s5, zmm.e5
  vmovdqu64 zmmword ptr [q.out + 320], zmm.s5
  vpxorq zmm.s6, zmm.s6, zmm.e6
  vmovdqu64 zmmword ptr [q.out + 384], zmm.s6
  vpxorq zmm.s7, zmm.s7, zmm.e7
  vmovdqu64 zmmword ptr [q.out + 448], zmm.s7
reverse12_l:
