  vpshufb zmm.e1, zmm.e1, zmm.bswap
  vpshufb zmm.e2, zmm.e2, zmm.bswap
  vpshufb zmm.e3, zmm.e3, zmm.bswap
  vpshufb zmm.e4, zmm.e4, zmm.bswap
  vpshufb zmm.e5, zmm.e5, zmm.bswap
  vpshufb zmm.e6, zmm.e6, zmm.bswap
  vpshufb zmm.e7, zmm.e7, zmm.bswap
  vpaddd zmm.base, zmm.base, zmmword ptr [rip + gcm_vaes_thirtytwo]
