  vpshufb zmm.e6, zmm.e6, zmm.bswap
  vpshufb zmm.e7, zmm.e7, zmm.bswap
  vpaddd zmm.base, zmm.base, zmmword ptr [rip + gcm_vaes_thirtytwo]
  add q.in, 512
  add q.out, 512
  add q.ret, 512
  sub q.len, 512
  cmp q.len, 512
  jae loop10
  jmp fin_fold
fin_fold:
  ;; ==== raw sums of the chunk before last: fold and reduce
  vpternlogq zmm.mid, zmm.lo, zmm.hi, 0x96      ; Karatsuba: mid = sum of the cross terms
  vpslldq zmm.r1, zmm.mid, 8
  vpsrldq zmm.r2, zmm.mid, 8
  vpxorq zmm.fl, zmm.lo, zmm.r1                ; mid folds into lo/hi (gcm_mul_raw)
  vpxorq zmm.fh, zmm.hi, zmm.r2
  vextracti64x4 ymm.r1, zmm.fl, 1
  vpxorq ymm.fl, ymm.fl, ymm.r1
  vextracti32x4 xmm.r1, ymm.fl, 1
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vextracti64x4 ymm.r2, zmm.fh, 1
  vpxorq ymm.fh, ymm.fh, ymm.r2
  vextracti32x4 xmm.r2, ymm.fh, 1
  vpxorq xmm.fh, xmm.fh, xmm.r2                ; four lanes to one
  vpslld xmm.r1, xmm.fl, 31                    ; fold modulo the polynomial (table rows carry x^-1)
  vpslld xmm.r2, xmm.fl, 30
  vpslld xmm.r3, xmm.fl, 25
  vpxorq xmm.r1, xmm.r1, xmm.r2
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpsrldq xmm.r2, xmm.r1, 4
  vpslldq xmm.r1, xmm.r1, 12
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vpsrld xmm.r1, xmm.fl, 1
  vpsrld xmm.r3, xmm.fl, 2
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpsrld xmm.r3, xmm.fl, 7
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpxorq xmm.r1, xmm.r1, xmm.r2
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vpxorq xmm.acc, xmm.fh, xmm.fl
fin_last:
  ;; ==== GHASH of the last chunk's ciphertext
  vpclmulqdq zmm.lo, zmm.e1, zmmword ptr [q.htab + 64], 0x00
  vpclmulqdq zmm.hi, zmm.e1, zmmword ptr [q.htab + 64], 0x11
  vpshufd zmm.t2, zmm.e1, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e1                  ; a0 ^ a1 in both halves
  vpclmulqdq zmm.mid, zmm.t2, zmmword ptr [q.htab + 576], 0x00
  vpclmulqdq zmm.t, zmm.e2, zmmword ptr [q.htab + 128], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e2, zmmword ptr [q.htab + 128], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e2, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e2
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 640], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpclmulqdq zmm.t, zmm.e3, zmmword ptr [q.htab + 192], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e3, zmmword ptr [q.htab + 192], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e3, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e3
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 704], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpclmulqdq zmm.t, zmm.e4, zmmword ptr [q.htab + 256], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e4, zmmword ptr [q.htab + 256], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e4, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e4
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 768], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpclmulqdq zmm.t, zmm.e5, zmmword ptr [q.htab + 320], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e5, zmmword ptr [q.htab + 320], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e5, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e5
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 832], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpclmulqdq zmm.t, zmm.e6, zmmword ptr [q.htab + 384], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e6, zmmword ptr [q.htab + 384], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e6, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e6
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 896], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpclmulqdq zmm.t, zmm.e7, zmmword ptr [q.htab + 448], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e7, zmmword ptr [q.htab + 448], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e7, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e7
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 960], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpxorq zmm.e0, zmm.e0, zmm.acc                 ; accumulator into block 0 (upper lanes of acc are zero)
  vpclmulqdq zmm.t, zmm.e0, zmmword ptr [q.htab], 0x00
  vpxorq zmm.lo, zmm.lo, zmm.t
  vpclmulqdq zmm.t, zmm.e0, zmmword ptr [q.htab], 0x11
  vpxorq zmm.hi, zmm.hi, zmm.t
  vpshufd zmm.t2, zmm.e0, 0x4e
  vpxorq zmm.t2, zmm.t2, zmm.e0
  vpclmulqdq zmm.t, zmm.t2, zmmword ptr [q.htab + 512], 0x00
  vpxorq zmm.mid, zmm.mid, zmm.t
  vpternlogq zmm.mid, zmm.lo, zmm.hi, 0x96      ; Karatsuba: mid = sum of the cross terms
  vpslldq zmm.r1, zmm.mid, 8
  vpsrldq zmm.r2, zmm.mid, 8
  vpxorq zmm.fl, zmm.lo, zmm.r1                ; mid folds into lo/hi (gcm_mul_raw)
  vpxorq zmm.fh, zmm.hi, zmm.r2
  vextracti64x4 ymm.r1, zmm.fl, 1
  vpxorq ymm.fl, ymm.fl, ymm.r1
  vextracti32x4 xmm.r1, ymm.fl, 1
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vextracti64x4 ymm.r2, zmm.fh, 1
  vpxorq ymm.fh, ymm.fh, ymm.r2
  vextracti32x4 xmm.r2, ymm.fh, 1
  vpxorq xmm.fh, xmm.fh, xmm.r2                ; four lanes to one
  vpslld xmm.r1, xmm.fl, 31                    ; fold modulo the polynomial (table rows carry x^-1)
  vpslld xmm.r2, xmm.fl, 30
  vpslld xmm.r3, xmm.fl, 25
  vpxorq xmm.r1, xmm.r1, xmm.r2
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpsrldq xmm.r2, xmm.r1, 4
  vpslldq xmm.r1, xmm.r1, 12
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vpsrld xmm.r1, xmm.fl, 1
  vpsrld xmm.r3, xmm.fl, 2
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpsrld xmm.r3, xmm.fl, 7
  vpxorq xmm.r1, xmm.r1, xmm.r3
  vpxorq xmm.r1, xmm.r1, xmm.r2
  vpxorq xmm.fl, xmm.fl, xmm.r1
  vpxorq xmm.acc, xmm.fh, xmm.fl
  vmovdqu64 xmmword ptr [q.p], xmm.acc
  mov q.p, qword ptr [q.ctx + 16]
  vpshufb xmm.t, xmm.base, xmm.bswap
  vmovdqu64 xmmword ptr [q.p], xmm.t
done:
  ret
.end

.rodata gcm_vaes_xinv align=64                  ; x^-1 in the reflected representation, per 128-bit lane
  .quad 1, 0xc200000000000000, 1, 0xc200000000000000, 1, 0xc200000000000000, 1, 0xc200000000000000
.end
.rodata gcm_vaes_xpow128 align=64               ; x^128 mod P = x^7 + x^2 + x + 1, reflected, per lane
  .quad 0, 0xe100000000000000, 0, 0xe100000000000000, 0, 0xe100000000000000, 0, 0xe100000000000000
.end
